def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    tokens = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "~": 3,
        ":": 4,
    }

    def parse(formula):
        values = []
        operators = []
        pending_function = None
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "~":
                values.append(("neg", values.pop()))
                return

            right = values.pop()
            left = values.pop()
            if op == ":":
                values.append(("range", left[1], right[1]))
            else:
                values.append(("binary", op, left, right))

        for match in tokens.finditer(formula):
            token = match.group()

            if token in functions:
                pending_function = token
            elif token == "(":
                operators.append(["(", pending_function, 0])
                pending_function = None
                expect_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][2] += 1
                expect_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = values[-count:]
                    del values[-count:]
                    if function == "IF":
                        values.append(("if", args[0], args[1], args[2]))
                    else:
                        values.append(("function", function, args))
                expect_operand = False
            elif token[0].isdigit():
                values.append(("number", int(token)))
                expect_operand = False
            elif token[0].isalpha():
                values.append(("reference", token))
                expect_operand = False
            elif token == "-" and expect_operand:
                operators.append("~")
            else:
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expect_operand = True

        while operators:
            reduce_operator()
        return values[0]

    def argument_nodes(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, last = arg[1], arg[2]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))
            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def calculate(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    memo = {}
    active = set()

    for root in cells:
        if root in memo:
            continue

        tasks = [("cell", root)]
        value = 0

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in memo:
                    value = memo[name]
                elif name not in cells:
                    value = 0
                elif name in active:
                    value = "#CYCLE!"
                else:
                    active.add(name)
                    tasks.append(("finish", name))
                    content = cells[name]
                    if content.startswith("="):
                        tasks.append(("node", parse(content[1:])))
                    else:
                        value = int(content)

            elif kind == "finish":
                name = task[1]
                memo[name] = value
                active.remove(name)

            elif kind == "node":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    value = node[1]
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("node", node[1]))
                elif node_kind == "binary":
                    tasks.append(("left", node[1], node[3]))
                    tasks.append(("node", node[2]))
                elif node_kind == "if":
                    tasks.append(("choose", node[2], node[3]))
                    tasks.append(("node", node[1]))
                else:
                    function = node[1]
                    args = argument_nodes(node[2])
                    initial = 0 if function == "SUM" else None
                    tasks.append(("next_argument", function, args, initial))

            elif kind == "negate":
                if not isinstance(value, str):
                    value = -value

            elif kind == "left":
                if not isinstance(value, str):
                    tasks.append(("right", task[1], value))
                    tasks.append(("node", task[2]))

            elif kind == "right":
                if not isinstance(value, str):
                    value = calculate(task[1], task[2], value)

            elif kind == "choose":
                if not isinstance(value, str):
                    tasks.append(("node", task[1] if value else task[2]))

            elif kind == "next_argument":
                _, function, args, accumulator = task
                node = next(args, None)
                if node is None:
                    value = 0 if accumulator is None else accumulator
                else:
                    tasks.append(("collect", function, args, accumulator))
                    tasks.append(("node", node))

            elif kind == "collect":
                if not isinstance(value, str):
                    _, function, args, accumulator = task
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(
                        ("next_argument", function, args, accumulator)
                    )

    return {name: memo[name] for name in cells}
